function getClueText(key,defaultText){if(!key)return defaultText||"";if(!key.startsWith("clue."))return key;if(translationCache[key])return translationCache[key];resolveTranslation(key).then(()=>{if(plonkitActive&&typeof updatePlonkitUI==="function"){updatePlonkitUI();}});return formatFallbackClueKey(key);}
function fetchZoomedImage(pano,clue){if(!pano||!clue)return Promise.resolve(null);if(clue.image&&(clue.image.startsWith("http")||clue.image.startsWith("data:"))){return Promise.resolve(clue.image);}
let query="";if(typeof clue.heading==="number"){query="heading="+encodeURIComponent(clue.heading)+
"&pitch="+encodeURIComponent(clue.pitch||0)+
"&fov="+encodeURIComponent(clue.fov||60);}else if(clue.cell){query="cell="+encodeURIComponent(clue.cell);}else{return Promise.resolve(null);}
return fetch("/api/v4/game-analysis/zoomed-image/"+encodeURIComponent(pano)+"?"+query,{credentials:"include"}).then(res=>res.ok?res.json():null).then(data=>{const img=data?.payload?.image||data?.image||null;if(img){clue.image=img;}
return img;}).catch(()=>null);}
function triggerCluesFetch(){const cc=(globalPlace.countryCode||"").toLowerCase();const pano=currentPanoId||"";if(!cc&&!pano)return;const cacheKey=`${cc}_${pano}`;if(cachedGeoGuessrClues.key===cacheKey&&(cachedGeoGuessrClues.countryClues.length>0||cachedGeoGuessrClues.panoClues.length>0)){return;}
cachedGeoGuessrClues.key=cacheKey;cachedGeoGuessrClues.countryCode=cc;cachedGeoGuessrClues.panoId=pano;cachedGeoGuessrClues.loading=true;cachedGeoGuessrClues.countryClues=[];cachedGeoGuessrClues.panoClues=[];cachedGeoGuessrClues.error=null;if(plonkitActive&&typeof updatePlonkitUI==="function"){updatePlonkitUI();}
const tasks=[];if(cc){tasks.push(fetch("/api/v4/clues/country/"+encodeURIComponent(cc)+"?count=8",{credentials:"include"}).then(res=>res.ok?res.json():null).then(data=>{let list=[];if(Array.isArray(data)){list=data;}else if(data&&Array.isArray(data.clues)){list=data.clues;}
cachedGeoGuessrClues.countryClues=list;list.forEach(item=>{if(item.title&&item.title.startsWith("clue."))resolveTranslation(item.title);if(item.description&&item.description.startsWith("clue."))resolveTranslation(item.description);});}).catch(()=>{}));}
if(pano){tasks.push(fetch("/api/v4/clues/"+encodeURIComponent(pano),{credentials:"include"}).then(res=>res.ok?res.json():null).then(async data=>{let list=[];if(Array.isArray(data)){list=data;}else if(data&&Array.isArray(data.clues)){list=data.clues;}
if(list.length===0){try{const scoutRes=await fetch("/api/v4/game-analysis/scout-clues/"+encodeURIComponent(pano),{credentials:"include"});if(scoutRes.ok){const scoutData=await scoutRes.json();const payload=scoutData?.payload||scoutData;if(Array.isArray(payload))list=payload;else if(Array.isArray(payload?.clues))list=payload.clues;}}catch(_){}}
cachedGeoGuessrClues.panoClues=list;const subTasks=[];list.forEach(item=>{if(item.title&&item.title.startsWith("clue.")){subTasks.push(resolveTranslation(item.title));}
if(item.description&&item.description.startsWith("clue.")){subTasks.push(resolveTranslation(item.description));}
if(!item.image&&(typeof item.heading==="number"||item.cell)){subTasks.push(fetchZoomedImage(pano,item));}});if(subTasks.length>0){await Promise.all(subTasks);}}).catch(()=>{}));}
Promise.all(tasks).finally(()=>{cachedGeoGuessrClues.loading=false;if(plonkitActive&&typeof updatePlonkitUI==="function"){updatePlonkitUI();}});}
