function createOrGetPlonkitIframe(){let iframe=document.getElementById("__adguards_plonkit_iframe");if(iframe)return iframe;iframe=document.createElement("iframe");iframe.id="__adguards_plonkit_iframe";iframe.style.position="fixed";iframe.style.top="60px";iframe.style.left="16px";iframe.style.width="390px";iframe.style.maxWidth="calc(100vw - 32px)";iframe.style.height="calc(100vh - 85px)";iframe.style.zIndex="2147483640";iframe.style.border="1px solid rgba(56, 189, 248, 0.4)";iframe.style.borderRadius="14px";iframe.style.boxShadow="0 16px 48px rgba(0, 0, 0, 0.85), 0 0 20px rgba(56, 189, 248, 0.15)";iframe.style.background="#090e1a";iframe.style.display="none";iframe.style.userSelect="none";(document.body||document.documentElement).appendChild(iframe);plonkitIframeEl=iframe;return iframe;}
